using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using SignFlow.Application.Common.Interfaces;
using SignFlow.Application.Common.Serialization;
using SignFlow.Domain.Enums;

namespace SignFlow.Application.Features.Reports.Queries;

/// <summary>
/// Portfolio-level risk mapping for administrators and managers: aggregates the risk analyses
/// already stored on each contract (<see cref="ContractRiskAnalysis"/>, generated by the mocked
/// keyword scan) — no new AI call is made here, this is pure aggregation of existing data.
/// </summary>
public record GetRiskMapQuery : IQuery<RiskMapDto>;

public record RiskMapDto(
    int TotalAnalyzed,
    double AvgRiskScore,
    List<SeverityCountDto> BySeverity,
    List<ClauseTypeFrequencyDto> TopClauseTypes,
    List<ContractFamilyRiskDto> ByRequestType);

public record SeverityCountDto(string Severity, int Count);
public record ClauseTypeFrequencyDto(string ClauseType, int Count);
public record ContractFamilyRiskDto(string RequestTypeName, int Count, double AvgRiskScore);

public class GetRiskMapQueryHandler(IApplicationDbContext db) : IQueryHandler<GetRiskMapQuery, RiskMapDto>
{
    public async Task<RiskMapDto> HandleAsync(GetRiskMapQuery query, CancellationToken cancellationToken = default)
    {
        // The risk analysis is stored as a JSON blob, not queryable server-side, so the
        // aggregation happens in memory once the (small) set of analysed contracts is loaded.
        var analysed = await db.Documents.AsNoTracking()
            .Where(d => d.AiRiskAnalysisJson != null)
            .Select(d => new
            {
                d.AiRiskAnalysisJson,
                RequestTypeName = d.RequestType != null ? d.RequestType.Name : null
            })
            .ToListAsync(cancellationToken);

        var parsed = analysed
            .Select(d => new
            {
                d.RequestTypeName,
                Risk = JsonSerializer.Deserialize<ContractRiskAnalysis>(d.AiRiskAnalysisJson!, ContractJson.Options)
            })
            .Where(d => d.Risk is not null)
            .Select(d => new { d.RequestTypeName, Risk = d.Risk! })
            .ToList();

        var total = parsed.Count;
        var avgScore = total == 0 ? 0 : Math.Round(parsed.Average(d => d.Risk.RiskScore), 1);

        var bySeverity = parsed
            .SelectMany(d => d.Risk.Findings)
            .GroupBy(f => f.Severity)
            .Select(g => new SeverityCountDto(g.Key, g.Count()))
            .OrderByDescending(s => s.Count)
            .ToList();

        var topClauseTypes = parsed
            .SelectMany(d => d.Risk.Findings)
            .GroupBy(f => f.ClauseType)
            .Select(g => new ClauseTypeFrequencyDto(g.Key, g.Count()))
            .OrderByDescending(c => c.Count)
            .Take(10)
            .ToList();

        var byRequestType = parsed
            .Where(d => d.RequestTypeName != null)
            .GroupBy(d => d.RequestTypeName!)
            .Select(g => new ContractFamilyRiskDto(g.Key, g.Count(), Math.Round(g.Average(d => d.Risk.RiskScore), 1)))
            .OrderByDescending(r => r.AvgRiskScore)
            .ToList();

        return new RiskMapDto(total, avgScore, bySeverity, topClauseTypes, byRequestType);
    }
}
